import{_ as o,o as a,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 51 话 GPU 合成与渲染性能","description":"","frontmatter":{},"headers":[],"relativePath":"comics/perf/EP.51-gpu-compositing.md","filePath":"comics/perf/EP.51-gpu-compositing.md","lastUpdated":1793421609000}'),c={name:"comics/perf/EP.51-gpu-compositing.md"};function i(l,e,d,n,s,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-51-话-gpu-合成与渲染性能" tabindex="-1">漫画 · 第 51 话 GPU 合成与渲染性能 <a class="header-anchor" href="#漫画-·-第-51-话-gpu-合成与渲染性能" aria-label="Permalink to &quot;漫画 · 第 51 话 GPU 合成与渲染性能&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/perf/03-gpu-compositing">docs/perf/03-gpu-compositing.md</a> ｜ 原画：<a href="./EP.51-gpu-compositing.svg">EP.51-gpu-compositing.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。写了个&quot;丝滑&quot;的卡片入场动画，真机上却像幻灯片；为了保险又给每张卡加了 <code>will-change</code>，结果更卡。</li><li><strong>标签君</strong>：结构师，在白板上画出 Style → Layout → Paint → Composite → GPU 的流水线，指出到底哪几站可以跳过。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱用 <code>left</code> 做位移动画，又把 60 张卡片的 <code>will-change: transform</code> 全部打开。帧率掉到 12fps，显存告急。标签君没有让她继续调参数，而是先画渲染流水线：动 <code>left</code> 每帧都要重新布局和绘制，动 <code>transform</code> 只走合成；而合成层不是免费的，每一层都是一张要占显存的纹理。问题从&quot;动画写法&quot;变成了&quot;预算问题&quot;。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>左边是属性选错：<code>left</code> 属于布局属性，每一帧都要重新计算布局、重绘，再合成上屏，主线程根本来不及。右边是层滥用：<code>will-change</code> 会提前把元素提升为独立合成层，60 张卡片就是 60 层纹理，显存与合成开销一起爆。两个错误叠加，滚动直接变成 PPT。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>渲染流水线五站：Style（样式计算）、Layout（布局）、Paint（绘制）、Composite（合成）、GPU（上屏）。只有 <code>transform</code>、<code>opacity</code> 这类合成属性可以跳过 Layout 与 Paint，直接从 Composite 开始。合成层树把页面拆成多个纹理，由 GPU 单独变换后拼回去，所以动画流畅；但层数越多，纹理面积越大，显存占用越高——层是预算，不是免费的加速开关。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>同一动画改成 <code>transform: translate3d()</code>，并且只给滑动容器提升一次层，掉帧从 42 次降到 0，合成层从 61 降到 3，帧率回到 58fps。三条铁律写在卡片上：只动合成属性、层提升只给容器一次、先看 FPS 与 Layers 面板再决定提升。优化顺序永远是&quot;测量 → 定位 → 最小改动&quot;。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>动画只动 <code>transform</code> / <code>opacity</code>，别动 <code>left</code>、<code>top</code>、宽高这类触发布局的属性。</li><li>合成层是预算：<code>will-change</code> 不是越多越好，每层都要显存与合成开销。</li><li>先测量再提升：看 FPS、掉帧与 Layers 面板，找到真凶再加 hack。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：给列表容器加了 <code>will-change: transform</code>，列表项滚动反而更卡，为什么？</p><p><strong>答</strong>：<code>will-change</code> 让容器提前成为合成层，但列表项本身如果也有阴影、圆角裁剪或 <code>position: sticky</code>，浏览器可能为子元素再建层，层数暴涨；同时大面积的容器纹理每次内容变化都要重新栅格化。正确做法是确认动画确实只在容器上做 transform，再提升一次；滚动容器优先用 <code>overscroll-behavior</code> 与 <code>contain</code> 控制影响范围，而不是无脑加 <code>will-change</code>。用完即撤，别长期挂着。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li><code>left</code> vs <code>transform</code> 掉帧对照 + Layers 面板观察：<a href="./../../examples/perf/03-gpu-compositing">examples/perf/03-gpu-compositing</a></li><li>打开 Chrome DevTools 的 Rendering → Frame Timing / Layer borders，边调 <code>will-change</code> 边看层数与掉帧。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>动画顺了，计算又堵住了主线程。第 52 话《主线程与长任务治理》——80 万行数据导出直接白屏，输入框打字没反应，看任务切片与 Worker 怎么救场。</p>',22)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
